<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/catalog.php';require_once __DIR__.'/../lib/validation.php';
send_cors_headers();$context=require_vendor(true);$vendorId=$context['vendor']['id'];$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';
if($method==='GET'){$id=trim((string)($_GET['id']??''));if($id!==''){$product=vendor_product($id,$vendorId);$variants=$db->prepare('SELECT v.*,i.stock_quantity,i.reserved_quantity,(i.stock_quantity-i.reserved_quantity) AS available_quantity,i.low_stock_threshold FROM product_variants v JOIN inventory_levels i ON i.variant_id=v.id WHERE v.product_id=:id ORDER BY v.created_at');$variants->execute(['id'=>$id]);json_response(200,['success'=>true,'product'=>$product,'variants'=>$variants->fetchAll()]);}$status=trim((string)($_GET['status']??''));$params=['vendor'=>$vendorId];$where='vendor_id=:vendor';if($status!==''){$where.=' AND status=:status';$params['status']=$status;}$stmt=$db->prepare("SELECT id,name,slug,sku,mrp,selling_price,status,rejection_reason,updated_at FROM products WHERE {$where} ORDER BY updated_at DESC");$stmt->execute($params);json_response(200,['success'=>true,'products'=>$stmt->fetchAll()]);}
if($method==='POST'||$method==='PUT'||$method==='PATCH'){$body=get_json_body();$rules=['name'=>'required|string|min:3|max:220','sku'=>'required|string|min:2|max:100','description'=>'required|string|min:40|max:10000','short_description'=>'string|max:500','mrp'=>'required|numeric','selling_price'=>'required|numeric','gst_percent'=>'required|numeric','material'=>'string|max:500','craft_technique'=>'string|max:300','dimensions'=>'string|max:255','origin_state'=>'string|max:80','gi_tag'=>'string|max:180','care_instructions'=>'string|max:3000','package_weight_grams'=>'required|integer','package_length_cm'=>'numeric','package_width_cm'=>'numeric','package_height_cm'=>'numeric','processing_min_days'=>'required|integer','processing_max_days'=>'required|integer'];$data=validate_fields($body,$rules);if((float)$data['mrp']<0||(float)$data['selling_price']<0||(float)$data['selling_price']>(float)$data['mrp']||(float)$data['gst_percent']<0||(float)$data['gst_percent']>100||(int)$data['package_weight_grams']<1||(int)$data['processing_min_days']<0||(int)$data['processing_max_days']<(int)$data['processing_min_days'])json_response(422,['success'=>false,'message'=>'Product price, tax, package weight or processing range is invalid.']);$id=$method==='POST'?uuid_string():trim((string)($_GET['id']??''));$db->beginTransaction();try{$existing=$method==='POST'?null:vendor_product($id,$vendorId,true);if($existing&&!in_array($existing['status'],['draft','changes_requested','rejected','approved','active','paused','out_of_stock'],true))json_response(409,['success'=>false,'message'=>'This product cannot be edited in its current state.']);$slug=unique_product_slug($db,(string)$data['name'],$id);$status=$existing&&in_array($existing['status'],['approved','active','paused','out_of_stock'],true)?'draft':'draft';$version=$existing?(int)$existing['review_version']+1:1;
    if($method==='POST'){$db->prepare('INSERT INTO products (id,vendor_id,name,slug,sku,short_description,description,mrp,selling_price,gst_percent,material,craft_technique,dimensions,origin_state,gi_tag,care_instructions,tags_json,package_weight_grams,package_length_cm,package_width_cm,package_height_cm,processing_min_days,processing_max_days,status,review_version,created_at,updated_at) VALUES (:id,:vendor,:name,:slug,:sku,:short_description,:description,:mrp,:selling_price,:gst_percent,:material,:craft_technique,:dimensions,:origin_state,:gi_tag,:care_instructions,:tags,:weight,:length,:width,:height,:min_days,:max_days,"draft",1,UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute(['id'=>$id,'vendor'=>$vendorId,'name'=>$data['name'],'slug'=>$slug,'sku'=>strtoupper((string)$data['sku']),'short_description'=>$data['short_description'],'description'=>$data['description'],'mrp'=>(float)$data['mrp'],'selling_price'=>(float)$data['selling_price'],'gst_percent'=>(float)$data['gst_percent'],'material'=>$data['material'],'craft_technique'=>$data['craft_technique'],'dimensions'=>$data['dimensions'],'origin_state'=>$data['origin_state'],'gi_tag'=>$data['gi_tag'],'care_instructions'=>$data['care_instructions'],'tags'=>isset($body['tags'])?json_encode(array_values((array)$body['tags'])):null,'weight'=>(int)$data['package_weight_grams'],'length'=>$data['package_length_cm'],'width'=>$data['package_width_cm'],'height'=>$data['package_height_cm'],'min_days'=>(int)$data['processing_min_days'],'max_days'=>(int)$data['processing_max_days']]);$variantId=uuid_string();$stock=max(0,(int)($body['stock']??0));$threshold=max(0,(int)($body['low_stock_threshold']??5));$db->prepare('INSERT INTO product_variants (id,product_id,sku,name,created_at) VALUES (:id,:product,:sku,"Default",UTC_TIMESTAMP())')->execute(['id'=>$variantId,'product'=>$id,'sku'=>strtoupper((string)$data['sku'])]);$db->prepare('INSERT INTO inventory_levels (variant_id,stock_quantity,reserved_quantity,low_stock_threshold,updated_at) VALUES (:variant,:stock,0,:threshold,UTC_TIMESTAMP())')->execute(['variant'=>$variantId,'stock'=>$stock,'threshold'=>$threshold]);$db->prepare('INSERT INTO inventory_movements (variant_id,vendor_id,movement_type,quantity_delta,reserved_delta,stock_after,reserved_after,note,actor_type,actor_id,created_at) VALUES (:variant,:vendor,"initial",:delta,0,:after,0,"Initial product stock","vendor",:actor,UTC_TIMESTAMP())')->execute(['variant'=>$variantId,'vendor'=>$vendorId,'delta'=>$stock,'after'=>$stock,'actor'=>$vendorId]);}
    else{$db->prepare('UPDATE products SET name=:name,slug=:slug,sku=:sku,short_description=:short_description,description=:description,mrp=:mrp,selling_price=:selling_price,gst_percent=:gst_percent,material=:material,craft_technique=:craft_technique,dimensions=:dimensions,origin_state=:origin_state,gi_tag=:gi_tag,care_instructions=:care_instructions,tags_json=:tags,package_weight_grams=:weight,package_length_cm=:length,package_width_cm=:width,package_height_cm=:height,processing_min_days=:min_days,processing_max_days=:max_days,status="draft",review_version=:version,rejection_reason=NULL,updated_at=UTC_TIMESTAMP() WHERE id=:id AND vendor_id=:vendor')->execute(['name'=>$data['name'],'slug'=>$slug,'sku'=>strtoupper((string)$data['sku']),'short_description'=>$data['short_description'],'description'=>$data['description'],'mrp'=>(float)$data['mrp'],'selling_price'=>(float)$data['selling_price'],'gst_percent'=>(float)$data['gst_percent'],'material'=>$data['material'],'craft_technique'=>$data['craft_technique'],'dimensions'=>$data['dimensions'],'origin_state'=>$data['origin_state'],'gi_tag'=>$data['gi_tag'],'care_instructions'=>$data['care_instructions'],'tags'=>isset($body['tags'])?json_encode(array_values((array)$body['tags'])):null,'weight'=>(int)$data['package_weight_grams'],'length'=>$data['package_length_cm'],'width'=>$data['package_width_cm'],'height'=>$data['package_height_cm'],'min_days'=>(int)$data['processing_min_days'],'max_days'=>(int)$data['processing_max_days'],'version'=>$version,'id'=>$id,'vendor'=>$vendorId]);}
    $product=vendor_product($id,$vendorId);$snapshot=product_snapshot($product);$db->prepare('INSERT INTO product_versions (id,product_id,version_number,snapshot_json,review_status,created_at) VALUES (:id,:product,:version,:snapshot,"draft",UTC_TIMESTAMP())')->execute(['id'=>uuid_string(),'product'=>$id,'version'=>$version,'snapshot'=>json_encode($snapshot,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);$db->commit();audit_event($method==='POST'?'vendor.product_created':'vendor.product_updated','product',$id,['version'=>$version]);json_response($method==='POST'?201:200,['success'=>true,'message'=>'Product draft saved.','product'=>$product]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
json_response(405,['success'=>false,'message'=>'Method not allowed.']);
